import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a directed network of {n_vertices} labeled nodes 1,2,...,{n_vertices}, for every pair i<j the edge is oriented i→j unless that pair is among a specified set of two-way edges. The two-way edges induce exactly one complete clique on {clique_size} nodes. In addition, there are {p_leaves} nodes outside this clique; each of these {p_leaves} nodes shares two-way edges with the same fixed set of {d_shared} clique nodes, and there are no two-way edges among the outside nodes. A subset of {t_size} distinct nodes is called mutually-connected if, using only the edges among those {t_size} nodes, every node can reach every other node (i.e., the induced subgraph on those nodes is strongly connected). Determine the exact number of mutually-connected {t_size}-subsets.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose parameters ensuring a nontrivial count and valid structure.
# s = clique_size, p = number of leaves, d = shared neighbors in clique, t = subset size
while True:
    s = rng.randint(7, 18)            # reasonably large clique
    p = rng.randint(2, 12)            # a handful of outside nodes
    d = rng.randint(2, s - 2)         # avoid trivial cases d=0 or d=s-1
    extra = rng.randint(0, 10)        # extra isolated nodes (no two-way edges)
    n = s + p + extra                 # total nodes
    t = rng.randint(4, min(6, s))     # ensure t <= s so clique contributes; and t >= 4 for difficulty
    # Validate that total two-way edges do not exceed total pairs
    total_pairs = n * (n - 1) // 2
    two_way_edges = s * (s - 1) // 2 + p * d
    if two_way_edges <= total_pairs and s >= 2 and p >= 2 and d <= s and t >= 2 and t <= n:
        return {
            'alpha': n,
            'n_vertices': n,
            'clique_size': s,
            'p_leaves': p,
            'd_shared': d,
            't_size': t
        }
    # else retry

    def verifier(assign):
# Verify domain constraints and compute the exact answer using a closed-form formula.
def comb(a, b):
    if b < 0 or a < 0 or b > a:
        return 0
    # Compute binomial coefficient safely
    # Use multiplicative formula to avoid large intermediate values
    b = min(b, a - b)
    num = 1
    den = 1
    for k in range(1, b + 1):
        num *= (a - b + k)
        den *= k
    return num // den

# Extract parameters
try:
    n = int(assign['n_vertices'])
    s = int(assign['clique_size'])
    p = int(assign['p_leaves'])
    d = int(assign['d_shared'])
    t = int(assign['t_size'])
    alpha = int(assign['alpha'])
except Exception:
    # Missing or invalid types
    return (False, None)

# Basic validations
if alpha != n:
    # alpha should mirror total nodes
    return (False, None)
if not (2 <= s <= n and 0 <= p <= n - s and 0 <= d <= s and 2 <= t <= n):
    return (False, None)
# Non-triviality conditions to enforce difficulty
if not (p >= 2 and t >= 4 and d >= 2 and d <= s - 2):
    return (False, None)

total_pairs = n * (n - 1) // 2
two_way_edges = s * (s - 1) // 2 + p * d
if two_way_edges > total_pairs:
    return (False, None)

# Core counting argument:
# Under the fixed linear orientation i->j for i<j, an induced subset is strongly connected
# iff the undirected graph formed by two-way edges within that subset is connected.
# Structure: K_s clique plus p leaves outside, all leaves adjacent (two-way) to the same set of d clique nodes.
# Count connected t-subsets:
# 1) Entirely within the clique: C(s, t).
# 2) Include u outside nodes (1 <= u <= min(p, t-1)) and v = t - u clique nodes.
#    Connectivity requires the chosen v-clique subset intersects the common d-neighbor set.
#    Number of such v-subsets: C(s, v) - C(s - d, v).
#    Choices of u outside nodes: C(p, u).

max_u = min(p, t - 1)
answer = comb(s, t)
for u in range(1, max_u + 1):
    v = t - u
    answer += comb(p, u) * (comb(s, v) - comb(s - d, v))

return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

